<template><section class="page-content"><div class="page-heading"><div><p class="eyebrow">PIUTANG PELANGGAN</p><h1>Utang</h1><p class="page-description">Pantau transaksi utang dan catat pelunasan pelanggan.</p></div></div><section class="panel"><div class="panel-header"><div><h2>Daftar Piutang</h2><p>{{ debts.length }} piutang tercatat</p></div></div><div class="table-wrap"><table><thead><tr><th>Pelanggan</th><th>Nomor Transaksi</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="debt in debts" :key="debt.id"><td>{{ debt.pelangganNama }}</td><td>{{ debt.nomor }}</td><td>{{ formatRupiah(debt.total) }}</td><td><span :class="['status-badge', debt.status === 'paid' ? 'status-locked' : 'status-draft']">{{ debt.status === 'paid' ? 'Lunas' : 'Belum Lunas' }}</span></td><td><div class="row-actions"><button class="action-button view-action" type="button" @click="detailDebt = debt">Detail</button><button v-if="debt.status !== 'paid'" class="action-button lock-action" type="button" @click="settle(debt)">Lunasi</button></div></td></tr><tr v-if="!debts.length"><td colspan="5" class="empty-cell">Belum ada data piutang.</td></tr></tbody></table></div></section><div v-if="detailDebt" class="modal-backdrop receipt-backdrop" @click.self="detailDebt = null"><section class="receipt-modal"><header class="receipt-modal-header"><div><p class="eyebrow">DETAIL PIUTANG</p><h2>{{ detailDebt.nomor }}</h2><p>{{ formatDate(detailDebt.tanggal) }} · {{ detailDebt.status === 'paid' ? 'Lunas' : 'Belum Lunas' }}</p></div><div class="receipt-header-actions"><button class="button button-secondary" type="button" @click="printDebt">Cetak</button><button class="modal-close" type="button" @click="detailDebt = null">×</button></div></header><div class="receipt-paper" id="debt-receipt"><div class="receipt-brand"><strong>WARUNG SEMBAKO</strong><span>Detail Piutang Pelanggan</span></div><div class="receipt-meta"><div><span>Nomor Transaksi</span><strong>{{ detailDebt.nomor }}</strong></div><div><span>Tanggal</span><strong>{{ formatDate(detailDebt.tanggal) }}</strong></div><div><span>Pelanggan</span><strong>{{ detailDebt.pelangganNama || 'Umum' }}</strong></div><div><span>Status</span><strong>{{ detailDebt.status === 'paid' ? 'Lunas' : 'Belum Lunas' }}</strong></div></div><div class="receipt-divider"></div><div class="receipt-items"><div v-for="item in detailDebt.items || []" :key="item.produkId" class="receipt-item"><div><strong>{{ item.nama }}</strong><small>{{ item.jumlah }} unit × {{ formatRupiah(item.hargaJualUnit) }}</small></div><strong>{{ formatRupiah(item.jumlah * item.hargaJualUnit) }}</strong></div></div><div class="receipt-divider"></div><div class="receipt-total"><span>Total Piutang</span><strong>{{ formatRupiah(detailDebt.total) }}</strong></div><div :class="['receipt-status', detailDebt.status === 'paid' ? 'receipt-status' : 'receipt-status-debt']">{{ detailDebt.status === 'paid' ? 'PIUTANG SUDAH LUNAS' : 'PIUTANG BELUM LUNAS' }}</div><p v-if="detailDebt.catatan" class="receipt-note">Catatan: {{ detailDebt.catatan }}</p><p class="receipt-thanks">Simpan bukti ini untuk arsip transaksi</p></div></section></div></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import Swal from 'sweetalert2'; import { collection, getDocs, query, where, updateDoc, doc } from 'firebase/firestore'; import { db } from '@/firebase'; import { authState } from '@/auth'; const debts=ref<any[]>([]); const detailDebt=ref<any|null>(null); const printDebt=()=>window.print(); const formatDate=(value:string)=>new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value)); const base=()=>`warungs/${authState.warungId}`; const formatRupiah=(value:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0); const load=async()=>{if(!authState.warungId)return; const snapshot=await getDocs(query(collection(db,base(),'sales'),where('metodePembayaran','==','utang'))); debts.value=snapshot.docs.map((item)=>({id:item.id,...item.data()}))}; const settle=async(debt:any)=>{const result=await Swal.fire({title:'Pelunasan utang',text:`Pilih metode pelunasan untuk ${formatRupiah(debt.total)}`,input:'select',inputOptions:{cash:'Cash',qris:'QRIS'},inputPlaceholder:'Pilih metode',showCancelButton:true,confirmButtonText:'Simpan',cancelButtonText:'Batal'}); if(result.isConfirmed&&result.value){await updateDoc(doc(db,base(),'sales',debt.id),{debtStatus:'paid',settledAt:new Date().toISOString(),settlementMethod:result.value});await load();await Swal.fire({title:'Utang lunas',icon:'success',confirmButtonColor:'#2563eb'})}}; onMounted(load);
</script>
